mod cli;mod duplicates;mod hashing;mod manifest;mod scanner;mod verify;use clap::Parser;use cli::{Cli,Command};use manifest::Manifest;use std::time::{SystemTime,UNIX_EPOCH};
fn main(){let cli=Cli::parse();let code=match run(cli){Ok(changed)=>if changed{1}else{0},Err(e)=>{eprintln!("error: {e}");2}};std::process::exit(code)}
fn run(cli:Cli)->Result<bool,String>{match cli.command{Command::Hash{file,algorithm}=>{let hash=hashing::hash_file(&file,algorithm).map_err(|e|e.to_string())?;let size=std::fs::metadata(&file).map_err(|e|e.to_string())?.len();println!("File: {}\nSize: {} bytes\nAlgorithm: {}\nChecksum: {}",file.display(),size,algorithm.name(),hash);Ok(false)},Command::Scan{path,hidden,algorithm,json,ignore}=>{let r=scanner::files(&path,hidden,&ignore,Some(algorithm))?;if json{println!("{}",serde_json::to_string_pretty(&r).map_err(|e|e.to_string())?)}else{for f in &r{println!("{}  {}  {}",f.hash.as_deref().unwrap_or(""),f.size,f.path)}println!("Total files: {}",r.len())}Ok(false)},Command::Duplicates{path,hidden,ignore}=>{let groups=duplicates::find(&path,hidden,&ignore)?;let mut recover=0;for(g,i)in groups.iter().zip(1..){println!("Duplicate Group {i}\nSHA-256: {}",g.hash);for p in &g.paths{println!("{} bytes  {p}",g.size)}recover+=(g.paths.len()-1)as u64*g.size}println!("Potential recoverable storage: {recover} bytes");Ok(false)},Command::Manifest{path,output,algorithm,ignore}=>{let m=Manifest{version:1,root:path.canonicalize().map_err(|e|e.to_string())?.to_string_lossy().to_string(),algorithm,created_at:SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e|e.to_string())?.as_secs().to_string(),files:scanner::files(&path,false,&ignore,Some(algorithm))?};manifest::write(&output,&m)?;println!("Wrote {} entries to {}",m.files.len(),output.display());Ok(false)},Command::Verify{manifest:path}=>{let m=manifest::read(&path)?;let r=verify::verify(&m)?;println!("Unchanged: {}\nModified: {}\nMissing: {}",r.unchanged,r.modified.len(),r.missing.len());for p in r.modified.iter().chain(r.missing.iter()){println!("- {p}")}Ok(!r.modified.is_empty()||!r.missing.is_empty())}}}
